css:
.mark{position:absolute}
.tri{width:0;height:0;border-left:8px solid transparent;border-right:8px solid transparent;border-bottom:13px solid #f43f5e;transform:rotate(28deg)}
.doodle{stroke:#f19cc4;stroke-width:1.5;fill:none} /* インラインSVG、人物のtop/left基準±30px */
.star{background:#c9a86a;clip-path:polygon(50% 0,58% 42%,100% 50%,58% 58%,50% 100%,42% 58%,0 50%,42% 42%)}
.star--s{width:10px;height:10px;opacity:.5}.star--l{width:32px;height:32px}
.dot{width:96px;height:96px;border-radius:50%;background:#0a0a0a;z-index:0}.dot--edge{left:-42px}
